      "rules": [
        {
          "rule": "{{cmd.regex_pattern}}",
          "eval": "{{eval}}",
          "severity": "error"
        }
      ]
    }{{ "," if not loop.last }}{% endfor %}{{ "," if not loop.last }}

    {% endfor %}
